mapper.select:
SELECT OrderNo AS orderNo, OrderDate AS orderDate, CustCode AS custCode, Qty AS qty, Discount AS discount, Cost AS cost, Status AS status, DeliveryDate AS deliveryDate, BankingYn AS bankingYn, CompleteYn AS completeYn FROM OrderMaster
CompleteYn = 'N'
AND CustCode = #{custCode}
AND OrderDate BETWEEN #{startDate} AND #{endDate}
ORDER BY OrderDate DESC, OrderNo DESC
